const key="smart-security-life-v1"; const id=()=>`${Date.now()}-${Math.random().toString(36).slice(2,7)}`; const vehicleType=(v:Vehicle["type"],custom?:string)=>v==="car"?"سيارة":v==="motorcycle"?"موتوسيكل":v==="tuk_tuk"?"توك توك":custom||"مركبة أخرى"; const vehicleVisitKind=(v:VehicleVisit["kind"])=>v==="inspection"?"فحص":v==="renewal"?"تجديد رخصة":v==="license"?"استخراج رخصة":v==="withdrawal"?"سحب رخصة":"أخرى"; const day=()=>new Date().toISOString().slice(0,10); const month=(v:string)=>v.slice(0,7); const cash=(v:number)=>`${Math.round(v||0).toLocaleString("ar-EG")} جنيه`;
function dueWithinTwoMonths(value?:string){return getLicenseAlertLevel(value)==="soon"}
function dateText(value?:string){return value?new Date(`${value}T12:00:00`).toLocaleDateString("ar-EG"):"غير محدد"}
async function shareText(text:string){try{if(navigator.share){await navigator.share({title:"جدول المرور - الإدارة الذكية",text});return}await navigator.clipboard.writeText(text);toast.success("تم نسخ جدول المرور للمشاركة")}catch{toast.error("تعذر المشاركة؛ يمكنك نسخ النص يدوياً")}}
function load():State{try{const p=JSON.parse(localStorage.getItem(key)||"null") as Partial<State>|null; return {...empty,...p,staff:Array.isArray(p?.staff)?p!.staff:[],workLocations:Array.isArray(p?.workLocations)?p!.workLocations:[],patrols:Array.isArray(p?.patrols)?p!.patrols:[],patrolPlans:Array.isArray(p?.patrolPlans)?p!.patrolPlans:[],entries:Array.isArray(p?.entries)?p!.entries:[],debts:Array.isArray(p?.debts)?p!.debts:[],children:Array.isArray(p?.children)?p!.children:[],teachers:Array.isArray(p?.teachers)?p!.teachers:[],lessons:Array.isArray(p?.lessons)?p!.lessons:[],vehicles:Array.isArray(p?.vehicles)?p!.vehicles:[],vehicleVisits:Array.isArray(p?.vehicleVisits)?p!.vehicleVisits:[],settings:{...empty.settings,...(p?.settings||{})}}}catch{return empty}}
type CloudRow=Record<string,any>;
const rows=(value:unknown)=>Array.isArray(value)?value as CloudRow[]:[];
function dateOnly(value:unknown){if(!value)return "";const d=value instanceof Date?value:new Date(String(value));return Number.isNaN(d.getTime())?"":d.toISOString().slice(0,10)}
function cloudState(snapshot:unknown,settings:State["settings"]):State{const data=(snapshot&&typeof snapshot==="object"?snapshot:{}) as Record<string,unknown>;return {settings,
staff:rows(data.staff).map(x=>({id:`staff-${x.id}`,code:x.staffCode||"",name:x.fullName||"",phone:x.phone||"",nationalId:x.nationalId||"",branch:x.branch||"",workStartDate:dateOnly(x.workStartDate),atm:x.atmLocation||"",hireDate:dateOnly(x.hireDate),rate:Number(x.monthlyRate)||0,active:x.isActive!==false,shift:x.shift||"morning",emergencyPhone:x.emergencyPhone||"",image:x.photoUrl||"",notes:x.notes||"",licenseStatus:x.licenseStatus||"unlicensed",weaponNumber:x.weaponNumber||"",licenseNumber:x.licenseNumber||"",licenseExpiry:dateOnly(x.licenseExpiry),retirementDate:dateOnly(x.retirementDate)})),
workLocations:rows(data.workLocations).map(x=>({id:`location-${x.id}`,staffId:x.staffId?`staff-${x.staffId}`:"",location:x.locationName||"",fromDate:dateOnly(x.fromDate),toDate:dateOnly(x.toDate),reason:x.transferReason||"",notes:x.notes||""})),
patrols:rows(data.patrols).map(x=>({id:`patrol-${x.id}`,staffId:x.staffId?`staff-${x.staffId}`:"",branch:x.branch||"",date:dateOnly(x.patrolDate),checkpoint:x.checkpoint||"",notes:x.notes||"",photo:x.photoUrl||""})),
patrolPlans:rows(data.patrolPlans).map(x=>({id:`plan-${x.id}`,date:dateOnly(x.planDate),branch:x.branch||"",checkpoint:x.checkpoint||"",staffId:x.staffId?`staff-${x.staffId}`:"",shift:x.shift||"morning",notes:x.notes||""})),
entries:rows(data.entries).map(x=>({id:`entry-${x.id}`,type:x.entryType==="expense"?"expense":"income",category:x.category||"",amount:Number(x.amount)||0,date:dateOnly(x.entryDate),notes:x.description||""})),
debts:rows(data.debts).map(x=>({id:`debt-${x.id}`,name:x.personName||"",direction:x.direction==="payable"?"payable":"receivable",total:Number(x.totalAmount)||0,paid:Number(x.paidAmount)||0,due:dateOnly(x.dueDate),notes:x.notes||""})),
children:rows(data.children).map(x=>({id:`child-${x.id}`,name:x.fullName||"",relation:x.relation||"ابن/ابنة",nationalId:x.nationalId||"",birthDate:dateOnly(x.birthDate),grade:x.grade||"",school:x.school||"",phone:x.phone||"",bloodType:x.bloodType||"",healthNotes:x.healthNotes||"",notes:x.notes||""})),
teachers:rows(data.teachers).map(x=>({id:`teacher-${x.id}`,name:x.fullName||"",subject:x.subject||"",phone:x.phone||"",whatsapp:x.whatsapp||"",cost:Number(x.monthlyCost)||0,availability:x.availability||"",notes:x.notes||""})),
lessons:rows(data.lessons).map(x=>({id:`lesson-${x.id}`,childId:x.childId?`child-${x.childId}`:"",teacherId:x.teacherId?`teacher-${x.teacherId}`:"",subject:x.subject||"",date:dateOnly(x.lessonDate),weekDay:x.weekDay||"",durationMinutes:Number(x.durationMinutes)||60,cost:Number(x.cost)||0,paidAmount:Number(x.paidAmount)||0,status:x.status==="completed"?"completed":x.status==="cancelled"?"cancelled":"scheduled"})),
vehicles:rows(data.vehicles).map(x=>({id:`vehicle-${x.id}`,type:x.vehicleType||"other",customType:x.customType||"",make:x.make||"",model:x.model||"",color:x.color||"",plate:x.plateNumber||"",vin:x.vin||"",purchaseDate:dateOnly(x.purchaseDate),saleDate:dateOnly(x.saleDate),ownership:x.ownership||"owned",licenseStatus:x.licenseStatus||"unlicensed",licenseNumber:x.licenseNumber||"",licenseExpiry:dateOnly(x.licenseExpiry),licenseWithdrawnDate:dateOnly(x.licenseWithdrawnDate),licenseWithdrawalReason:x.licenseWithdrawalReason||"",notes:x.notes||""})),
vehicleVisits:rows(data.vehicleVisits).map(x=>({id:`vehicle-visit-${x.id}`,vehicleId:x.vehicleId?`vehicle-${x.vehicleId}`:"",date:dateOnly(x.visitDate),kind:x.visitType||"other",result:x.result||"",nextDue:dateOnly(x.nextDueDate),fees:Number(x.fees)||0,notes:x.notes||""}))}}
function csv(file:string,rows:Record<string,unknown>[]){const ks=rows[0]?Object.keys(rows[0]):["البيان"];const esc=(v:unknown)=>`"${String(v??"").replaceAll('"','""')}"`;const text="\uFEFF"+ks.join(",")+"\n"+rows.map(r=>ks.map(k=>esc(r[k])).join(",")).join("\n");const u=URL.createObjectURL(new Blob([text],{type:"text/csv;charset=utf-8"}));const a=document.createElement("a");a.href=u;a.download=file;a.click();URL.revokeObjectURL(u)}
function print(title:string,rows:Record<string,unknown>[]){const w=window.open("","_blank","noopener,noreferrer");if(!w){toast.error("اسمح بالنوافذ المنبثقة لإنشاء التقرير");return}const ks=rows[0]?Object.keys(rows[0]):["البيان"];w.document.write(`<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>${title}</title><style>@page{size:A4;margin:15mm}body{font-family:Arial;color:#0f172a}.head{border-bottom:3px solid #0f766e;padding-bottom:12px;margin-bottom:20px}.head b{font-size:25px;color:#0f766e}.head span{margin-right:20px;font-size:18px;font-weight:bold}table{width:100%;border-collapse:collapse}th,td{border:1px solid #cbd5e1;padding:8px;font-size:12px;text-align:right}th{background:#0f766e;color:#fff}</style></head><body><div class="head"><b>الإدارة الذكية</b><span>${title}</span></div><table><thead><tr>${ks.map(k=>`<th>${k}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr>${ks.map(k=>`<td>${r[k]??""}</td>`).join("")}</tr>`).join("")}</tbody></table><script>onload=()=>print()</script></body></html>`);w.document.close()}
async function image(file:File){return new Promise<string>((resolve,reject)=>{const r=new FileReader();const im=new Image();r.onload=()=>{im.onload=()=>{const s=Math.min(1,1200/Math.max(im.width,im.height));const c=document.createElement("canvas");c.width=Math.round(im.width*s);c.height=Math.round(im.height*s);c.getContext("2d")!.drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL("image/jpeg",.78))};im.onerror=()=>reject(new Error("image"));im.src=String(r.result)};r.onerror=()=>reject(new Error("file"));r.readAsDataURL(file)})}
const Input=(p:React.InputHTMLAttributes<HTMLInputElement>)=><input {...p} className={`field-input ${p.className||""}`}/>;
const Select=(p:React.SelectHTMLAttributes<HTMLSelectElement>)=><select {...p} className={`field-input ${p.className||""}`}/>;
